-- =============================================================================
-- 10_finance.sql  -  schema "finance": general ledger, budgets, FX (SYNTHETIC)
-- The COMMENT ON statements below are the schema documentation shown in the UI.
-- =============================================================================
SET timezone TO 'UTC';

COMMENT ON SCHEMA finance IS
'Accounting data of Nimbus Markets, a FICTIONAL multi-asset broker. 100% synthetic, generated by scripts/generate_synthetic_data.py. '
'Four legal entities (finance.entities) post daily/monthly P&L lines to the general ledger (finance.gl_entries) against a chart of accounts (finance.accounts); '
'monthly targets live in finance.budgets and daily currency-to-USD rates in finance.fx_rates. '
'All money columns ending in _usd are US dollars. Revenue and expense amounts are both stored as POSITIVE magnitudes: use accounts.account_type to tell them apart '
'(operating profit = SUM(revenue) - SUM(expense)). The data covers roughly the 18 months up to the current month; the current month is month-to-date. '
'Used by the finance_agent; join to the trading schema only via the client country -> entity mapping documented on trading.clients.country.';

-- ---------------------------------------------------------------------------
CREATE TABLE finance.entities (
    entity_id text PRIMARY KEY,
    name      text    NOT NULL,
    country   text    NOT NULL,
    currency  char(3) NOT NULL
);
COMMENT ON TABLE finance.entities IS
'Legal entities of the (fictional) Nimbus Markets group, one row each: NM-UK (GBP), NM-SG (SGD), NM-AE (AED), NM-INTL (USD). '
'Every GL line and budget line belongs to exactly one entity. Trading clients map to an entity by their country (see trading.clients.country).';
COMMENT ON COLUMN finance.entities.entity_id IS 'Entity code, primary key. One of NM-UK, NM-SG, NM-AE, NM-INTL. Join key for gl_entries.entity_id and budgets.entity_id.';
COMMENT ON COLUMN finance.entities.name      IS 'Legal name of the fictional entity, e.g. "Nimbus Markets UK Ltd".';
COMMENT ON COLUMN finance.entities.country   IS 'ISO 3166-1 alpha-2 country of incorporation (GB, SG, AE, MU).';
COMMENT ON COLUMN finance.entities.currency  IS 'Functional (local) currency, ISO 4217: GBP, SGD, AED or USD. GL amount_local is in this currency.';

-- ---------------------------------------------------------------------------
CREATE TABLE finance.accounts (
    account_code text PRIMARY KEY,
    account_name text NOT NULL,
    account_type text NOT NULL CHECK (account_type IN ('revenue', 'expense', 'asset', 'liability', 'equity')),
    category     text NOT NULL
);
COMMENT ON TABLE finance.accounts IS
'Chart of accounts (fictional). 4xxx = revenue, 5xxx = expense, 1xxx-3xxx = balance-sheet accounts (listed for completeness; the GL only contains P&L activity). '
'Group by category for management reporting: revenue categories are Trading commission, Spread revenue, Subscription fees, Interest income; '
'expense categories are Staff costs, Marketing, Technology, Office & admin, Payment processing, Professional fees.';
COMMENT ON COLUMN finance.accounts.account_code IS 'Account number as text, primary key, e.g. ''4100'' (Trading commission revenue). Join key for gl_entries.account_code and budgets.account_code.';
COMMENT ON COLUMN finance.accounts.account_name IS 'Human-readable account name, e.g. "Performance marketing".';
COMMENT ON COLUMN finance.accounts.account_type IS 'One of: revenue, expense, asset, liability, equity. Decides the sign in P&L maths: profit = SUM(amount_usd) FILTER (WHERE account_type=''revenue'') - SUM(amount_usd) FILTER (WHERE account_type=''expense'').';
COMMENT ON COLUMN finance.accounts.category     IS 'Reporting category used for P&L breakdowns and budget-vs-actual, e.g. Trading commission, Spread revenue, Marketing, Staff costs. Several accounts can share one category.';

-- ---------------------------------------------------------------------------
CREATE TABLE finance.fx_rates (
    rate_date date          NOT NULL,
    currency  char(3)       NOT NULL,
    usd_rate  numeric(18,8) NOT NULL CHECK (usd_rate > 0),
    PRIMARY KEY (rate_date, currency)
);
COMMENT ON TABLE finance.fx_rates IS
'Daily synthetic FX rates to US dollars, one row per calendar day per currency (AED, EUR, GBP, SGD, USD; weekends carry Friday''s rate). '
'1 unit of currency = usd_rate USD, so amount_usd = amount_local * usd_rate and amount_local = amount_usd / usd_rate. USD rows are always 1. '
'EUR and GBP follow the synthetic EURUSD / GBPUSD closes in trading.daily_prices.';
COMMENT ON COLUMN finance.fx_rates.rate_date IS 'Calendar date of the rate (every day in the data window).';
COMMENT ON COLUMN finance.fx_rates.currency  IS 'ISO 4217 code: AED, EUR, GBP, SGD or USD. Join to gl_entries.currency / entities.currency.';
COMMENT ON COLUMN finance.fx_rates.usd_rate  IS 'USD value of ONE unit of the currency on rate_date (e.g. GBP ~ 1.27). Multiply a local amount by it to get USD.';

-- ---------------------------------------------------------------------------
CREATE TABLE finance.gl_entries (
    entry_id     bigint        PRIMARY KEY,
    entry_date   date          NOT NULL,
    entity_id    text          NOT NULL REFERENCES finance.entities (entity_id),
    account_code text          NOT NULL REFERENCES finance.accounts (account_code),
    amount_local numeric(18,2) NOT NULL,
    currency     char(3)       NOT NULL,
    amount_usd   numeric(18,2) NOT NULL,
    description  text          NOT NULL
);
COMMENT ON TABLE finance.gl_entries IS
'General ledger P&L lines (synthetic, ~16k rows). One row = one posting of revenue or expense for one entity and account on one date. '
'SIGN CONVENTION: amounts are positive magnitudes for BOTH revenue and expense; join finance.accounts and use account_type to decide whether a line adds to or subtracts from profit. '
'Trading commission (account 4100) is booked daily per entity and asset class from closed trades and reconciles with SUM(trading.trades.commission_usd) for that entity''s clients and month (differences are cents of FX rounding). '
'Spread revenue (4200) is booked daily from opened trades, subscriptions (4300) weekly, interest (4400) at month end, expenses on invoice dates. '
'Typical pattern: SELECT date_trunc(''month'', g.entry_date)::date AS month, a.category, SUM(g.amount_usd) FROM finance.gl_entries g JOIN finance.accounts a USING (account_code) GROUP BY 1, 2.';
COMMENT ON COLUMN finance.gl_entries.entry_id     IS 'Surrogate key, increasing with entry_date.';
COMMENT ON COLUMN finance.gl_entries.entry_date   IS 'Posting date (date, no time). Use date_trunc(''month'', entry_date)::date to bucket by month, matching budgets.month.';
COMMENT ON COLUMN finance.gl_entries.entity_id    IS 'Entity that booked the line. FK -> finance.entities.entity_id (NM-UK, NM-SG, NM-AE, NM-INTL).';
COMMENT ON COLUMN finance.gl_entries.account_code IS 'Account posted to. FK -> finance.accounts.account_code; join it to get account_type (revenue/expense) and category.';
COMMENT ON COLUMN finance.gl_entries.amount_local IS 'Positive magnitude in the entity''s local currency (column currency), 2 dp.';
COMMENT ON COLUMN finance.gl_entries.currency     IS 'ISO 4217 currency of amount_local; always the entity''s functional currency.';
COMMENT ON COLUMN finance.gl_entries.amount_usd   IS 'Positive magnitude in US dollars = amount_local * fx_rates.usd_rate on entry_date, rounded to cents. Use this column for all cross-entity totals.';
COMMENT ON COLUMN finance.gl_entries.description  IS 'Free-text narrative, e.g. "Trading commission - crypto - 2026-10-14" or "Performance marketing - search ads". Handy for ILIKE filters (e.g. asset class of a commission line).';

CREATE INDEX gl_entries_entry_date_idx   ON finance.gl_entries (entry_date);
CREATE INDEX gl_entries_account_code_idx ON finance.gl_entries (account_code);
CREATE INDEX gl_entries_entity_date_idx  ON finance.gl_entries (entity_id, entry_date);

-- ---------------------------------------------------------------------------
CREATE TABLE finance.budgets (
    month        date          NOT NULL CHECK (EXTRACT(day FROM month) = 1),
    entity_id    text          NOT NULL REFERENCES finance.entities (entity_id),
    account_code text          NOT NULL REFERENCES finance.accounts (account_code),
    budget_usd   numeric(18,2) NOT NULL,
    PRIMARY KEY (month, entity_id, account_code)
);
COMMENT ON TABLE finance.budgets IS
'Monthly budget (plan) per entity and P&L account, in USD, positive magnitudes like the GL. One row per month x entity x revenue/expense account. '
'Compare with actuals by joining on entity_id, account_code and date_trunc(''month'', gl_entries.entry_date)::date = budgets.month; aggregate both sides BEFORE joining to avoid double counting. '
'For revenue, actual above budget is good; for expenses, actual above budget is an overrun. The current month''s budget is a full-month figure while actuals are month-to-date.';
COMMENT ON COLUMN finance.budgets.month        IS 'First day of the budget month (e.g. 2026-08-01). Always day 1.';
COMMENT ON COLUMN finance.budgets.entity_id    IS 'FK -> finance.entities.entity_id.';
COMMENT ON COLUMN finance.budgets.account_code IS 'FK -> finance.accounts.account_code (revenue and expense accounts only). Join accounts for category / account_type.';
COMMENT ON COLUMN finance.budgets.budget_usd   IS 'Budgeted amount for the whole month in USD (positive magnitude).';

CREATE INDEX budgets_entity_month_idx ON finance.budgets (entity_id, month);
